"""MEMBER B. Template-based synthetic TRAINING data, generated by code (seeded -> identical on every run; no API cost).

Rules (Kaggle Rules tab s.4): creating additional training examples yourself is allowed if the process is reproducible
from the notebook and no test text or test prediction is copied in. These templates are written from the labelling guide
on the Data tab (class definitions, priority order, T1..T6 and action definitions, conventions) - never from test.csv.
Declare in the notebook: "template-generated synthetic training data (written with an AI coding assistant)".

Coverage, aimed at the hidden evaluation subsets:
  - every class x English / Banglish / Bangla script, with invented brands and sender identities (novel scenarios)
  - priority-order cases (prize + OTP -> 1, gift parcel + customs fee -> 2, job + OTP -> 1)
  - hard legitimate cases (OTP delivery with warning, transaction / delivery / bill notices, warnings ABOUT scams)
  - registers (domain shift): SMS, multi-turn chats with varied speaker markers and late reveals, call transcripts,
    group chats, formal emails, long notices
Each generated row carries label, techniques (T1..T6) and action consistent with the guide's conventions."""
import random

import pandas as pd

MFS = ["bKash", "Nagad", "Rocket", "Upay", "TakaPay", "PayDhaka", "mCash BD"]
BANK = ["DBBL", "City Bank", "BRAC Bank", "Islami Bank", "Sonali Bank", "EBL", "Prime Bank", "Meghna Trust Bank"]
TELCO = ["GP", "Grameenphone", "Robi", "Banglalink", "Airtel", "Teletalk", "SkyTel BD"]
COURIER = ["Sundarban Courier", "SA Paribahan", "RedX", "Steadfast", "Pathao Courier", "eCourier", "Paperfly", "DHL",
           "QuickParcel BD", "Dhaka Express Courier", "Bangla Post"]
SHOP = ["Daraz", "Chaldal", "Foodpanda", "Shajgoj", "Othoba", "Rokomari", "Aarong", "ShopNest", "BuyKoro", "Pickaboo"]
GOV = ["BTRC", "NBR", "Election Commission", "DESCO", "Titas Gas", "BREB", "WASA", "Passport Office"]
JOBSRC = ["Bdjobs", "LinkedIn", "Facebook page", "Telegram channel", "a recruitment agency"]
NAMES = ["Rahim", "Karim", "Nusrat", "Tania", "Sabbir", "Mitu", "Arif", "Jannat", "Rafi", "Sumi", "Imran", "Lima"]
TLD = ["top", "xyz", "click", "site", "online", "info", "shop", "live", "vip"]
URGENT_EN = ["within 1 hour", "today only", "immediately", "before midnight", "or your account will be blocked",
             "within 24 hours", "last chance"]
URGENT_BN = ["1 ghontar moddhe", "aj-i", "ekhoni", "na hole account band hobe", "24 ghontar moddhe", "taratari"]
URGENT_BS = ["১ ঘণ্টার মধ্যে", "আজই", "এখনই", "না হলে অ্যাকাউন্ট বন্ধ হয়ে যাবে", "২৪ ঘণ্টার মধ্যে"]


def _amt(r, lo=50, hi=50000):
    return f"{r.randrange(lo, hi, 10):,}"


def _url(r, word):
    return f"hxxps://{word.lower().replace(' ', '-')}-{r.choice(['bd', 'verify', 'claim', 'help', 'pay', 'secure'])}[.]{r.choice(TLD)}/{r.randint(10, 999)}"


def _legit_url(org):
    return f"https://www[.]{org.lower().replace(' ', '')}[.]com[.]bd"


def _code(r):
    return str(r.randint(100000, 999999))


# ---------------------------------------------------------------- scam / legit cores: (text, label, techniques, action)
def mfs_scam(r, lang):
    org = r.choice(MFS + BANK)
    k = r.randint(0, 5)
    if k == 0:   # account lock -> credential request
        t = {"en": f"{org} Security: your account is temporarily locked. Reply with the 6 digit OTP to reactivate {r.choice(URGENT_EN)}.",
             "bn": f"{org} theke bolchi. Apnar account e unusual login hoyeche, OTP ta din {r.choice(URGENT_BN)}.",
             "bs": f"{org} অফিস থেকে বলছি। আপনার অ্যাকাউন্টে সমস্যা হয়েছে, ভেরিফাই করতে ওটিপি কোডটি দিন, {r.choice(URGENT_BS)}।"}[lang]
        return t, 1, {"T1", "T2", "T5"}, 1
    if k == 1:   # mistaken transfer, asks money back
        a = _amt(r, 500, 9000)
        t = {"en": f"Sorry brother, I sent Tk {a} to your number by mistake. Please send it back to 01XXXXXXXXX, I am in trouble.",
             "bn": f"Bhai ami bhul kore apnar number e {a} taka pathaisi. Please ferot den 01XXXXXXXXX ei number e.",
             "bs": f"ভাই, ভুল করে আপনার নম্বরে {a} টাকা চলে গেছে। দয়া করে টাকাটা ফেরত দিন, খুব বিপদে আছি।"}[lang]
        return t, 1, {"T3", "T5"}, 2
    if k == 2:   # agent + mistaken transfer + PIN
        t = {"en": f"I am a {org} agent, money went to your account by mistake. To reverse it tell me your PIN.",
             "bn": f"Ami {org} agent, bhul number-e taka chole gese. Ferot dite apnar PIN ta bolen.",
             "bs": f"আমি {org} এজেন্ট, ভুল নম্বরে টাকা চলে গেছে। ফেরত দিতে আপনার পিন নম্বরটি বলুন।"}[lang]
        return t, 1, {"T1", "T2", "T5"}, 1
    if k == 3:   # card details
        t = {"en": f"{org} card services: send card number, expiry date and CVV to stop an unauthorised payment of Tk {_amt(r)}.",
             "bn": f"{org} card team: Tk {_amt(r)} er ekta payment block korte card number, expiry ar CVV pathan.",
             "bs": f"{org} কার্ড সার্ভিস: অননুমোদিত লেনদেন বন্ধ করতে কার্ড নম্বর, মেয়াদ ও সিভিভি পাঠান।"}[lang]
        return t, 1, {"T1", "T2"}, 1
    if k == 4:   # KYC / NID via link (credentials win over link)
        t = {"en": f"Dear {org} user, complete KYC at {_url(r, org)} with your NID and PIN or your wallet will be closed {r.choice(URGENT_EN)}.",
             "bn": f"Dear {org} user, KYC update korte {_url(r, org)} e NID number ar PIN din, na hole account band hobe.",
             "bs": f"প্রিয় {org} গ্রাহক, কেওয়াইসি আপডেট করতে লিংকে গিয়ে এনআইডি ও পিন দিন, না হলে অ্যাকাউন্ট বন্ধ হবে।"}[lang]
        return t, 1, {"T1", "T2", "T5"}, 1
    # priority: prize that asks for OTP -> class 1
    t = {"en": f"Congratulations! You won Tk {_amt(r, 1000, 100000)} in the {org} lucky draw. Share your OTP to receive it.",
         "bn": f"Ovinondon! Apni {org} lucky draw te Tk {_amt(r, 1000, 100000)} jitechen. Taka pete OTP ta share korun.",
         "bs": f"অভিনন্দন! আপনি {org} লাকি ড্রতে {_amt(r, 1000, 100000)} টাকা জিতেছেন। টাকা পেতে ওটিপি কোডটি দিন।"}[lang]
    return t, 1, {"T1", "T4", "T2"}, 1


