def parcel_scam(r, lang):
    org = r.choice(COURIER)
    pid = f"{org[:2].upper()}{r.randint(1000, 99999)}"
    k = r.randint(0, 3)
    if k == 0:   # storage / delivery fee via link
        t = {"en": f"{org}: Parcel {pid} is on hold. Pay Tk {_amt(r, 30, 200)} storage fee: {_url(r, org)}",
             "bn": f"{org}: Parcel {pid} atke ase. Delivery fee Tk {_amt(r, 30, 200)} dite link e jan {_url(r, org)}",
             "bs": f"{org}: আপনার পার্সেল {pid} আটকে আছে। ডেলিভারি চার্জ {_amt(r, 30, 200)} টাকা পরিশোধ করতে লিংকে ক্লিক করুন।"}[lang]
        return t, 4, {"T1", "T3"}, 2
    if k == 1:   # address confirmation link
        t = {"en": f"{org}: your package {pid} could not be delivered. Confirm your address at {_url(r, org)} {r.choice(URGENT_EN)}.",
             "bn": f"{org}: parcel {pid} deliver kora jayni. Address confirm korun {_url(r, org)}",
             "bs": f"{org}: আপনার পার্সেল ডেলিভারি করা যায়নি। ঠিকানা নিশ্চিত করতে লিংকে যান।"}[lang]
        return t, 4, {"T1", "T5"} if lang == "en" else {"T1"}, 3
    if k == 2:   # customs duty via MFS
        t = {"en": f"Customs hold: your parcel from China needs Tk {_amt(r, 800, 5000)} duty. Pay via bKash 01XXXXXXXXX to release.",
             "bn": f"Customs e apnar parcel atke ase. Tk {_amt(r, 800, 5000)} duty bKash e pathan.",
             "bs": f"কাস্টমসে আপনার পার্সেল আটকে আছে। ছাড়াতে {_amt(r, 800, 5000)} টাকা শুল্ক বিকাশে পাঠান।"}[lang]
        return t, 4, {"T1", "T3"}, 2
    t = {"en": f"{org}: delivery failed for parcel {pid}. Call our agent at 01XXXXXXXXX to reschedule {r.choice(URGENT_EN)}.",
         "bn": f"{org}: parcel {pid} delivery fail hoyeche. Reschedule korte 01XXXXXXXXX e call korun.",
         "bs": f"{org}: পার্সেল {pid} ডেলিভারি ব্যর্থ হয়েছে। আবার পেতে এই নম্বরে কল করুন।"}[lang]
    return t, 4, {"T1", "T5"}, 5


