def legit(r, lang):
    org = r.choice(MFS + BANK + TELCO + SHOP + COURIER + GOV)
    k = r.randint(0, 8)
    if k == 0:   # OTP delivery with warning (hard negative)
        t = {"en": f"{org} OTP: {_code(r)}. Valid for 3 minutes. Never share this code with anyone, {org} will never ask for it.",
             "bn": f"{org} OTP: {_code(r)}. Eta kauke bolben na. Meyad 3 minute.",
             "bs": f"{org} ওটিপি: {_code(r)}। কাউকে বলবেন না। মেয়াদ ৩ মিনিট।"}[lang]
    elif k == 1:  # transaction notice
        t = {"en": f"Cash Out Tk {_amt(r, 100, 9000)} successful. Fee Tk {_amt(r, 2, 90)}. Balance Tk {_amt(r)}. TrxID {r.randint(10**8, 10**9)}",
             "bn": f"Apnar cash-out {_amt(r, 100, 9000)} taka successful. Balance {_amt(r)} taka.",
             "bs": f"আপনার {_amt(r, 100, 9000)} টাকা ক্যাশ আউট সফল হয়েছে। বর্তমান ব্যালেন্স {_amt(r)} টাকা।"}[lang]
    elif k == 2:  # genuine delivery update
        t = {"en": f"Your {r.choice(SHOP)} order #{r.randint(1000, 99999)} has been shipped and will arrive by {r.randint(1, 28)} Dec.",
             "bn": f"Apnar order ajke deliver hobe. Rider call korbe, cash on delivery.",
             "bs": f"আপনার অর্ডারটি আজ ডেলিভারি হবে। রাইডার কল করবেন।"}[lang]
    elif k == 3:  # bill reminder
        t = {"en": f"Reminder: your {org} bill of Tk {_amt(r, 300, 5000)} is due on {r.randint(1, 28)} Dec. Pay via the official app.",
             "bn": f"{org} bill Tk {_amt(r, 300, 5000)} er last date {r.randint(1, 28)} Dec. Official app theke pay korun.",
             "bs": f"আপনার {org} বিল {_amt(r, 300, 5000)} টাকা, শেষ তারিখ {r.randint(1, 28)} ডিসেম্বর।"}[lang]
    elif k == 4:  # message ABOUT a scam (class 0)
        t = {"en": "Be careful, I got a message saying I won 5 lakh taka and must click a link. It is a scam, don't fall for it.",
             "bn": "Sabdhan! Keu bKash agent bole PIN chaile diben na, eta protarona. Amar kase o emon call ashchilo.",
             "bs": "সাবধান! কেউ বিকাশ এজেন্ট পরিচয়ে পিন চাইলে দেবেন না, এটা প্রতারণা।"}[lang]
    elif k == 5:  # personal chat
        n1, n2 = r.sample(NAMES, 2)
        t = {"en": f"A: {n1}, are we meeting at 5? ||| B: yes, see you at the tea stall ||| A: ok",
             "bn": f"A: bhai, {_amt(r, 500, 3000)} taka ferot dibi kobe? ||| B: sunday dibo, bkash e pathaya dibo ||| A: ok thik ase",
             "bs": "A: আজ বিকেলে আসবি? ||| B: হ্যাঁ, পাঁচটায় আসছি ||| A: ঠিক আছে"}[lang]
    elif k == 6:  # support conversation with genuine advice
        t = {"en": f"R: I forgot my {org} PIN. How can I reset it? ||| S: Dial *247# and choose Reset PIN. Never share your PIN with anyone.",
             "bn": f"R: {org} PIN vule gesi, ki korbo? ||| S: *247# dial kore Reset PIN select korun. PIN kauke diben na.",
             "bs": "R: পিন ভুলে গেছি, কী করব? ||| S: *২৪৭# ডায়াল করে রিসেট করুন। পিন কাউকে দেবেন না।"}[lang]
    elif k == 7:  # refund credited / payment confirmation
        t = {"en": f"Your {r.choice(SHOP)} refund of Tk {_amt(r, 100, 3000)} has been credited to your {r.choice(MFS)} account.",
             "bn": f"Apnar {_amt(r, 100, 3000)} taka refund apnar {r.choice(MFS)} account e joma hoyeche.",
             "bs": f"আপনার {_amt(r, 100, 3000)} টাকা রিফান্ড অ্যাকাউন্টে জমা হয়েছে।"}[lang]
    else:         # official notice with a real link (link alone is not suspicious)
        t = {"en": f"{org}: scheduled maintenance tonight 1-3 AM. Details: {_legit_url(org)}",
             "bn": f"{org}: aj raat 1-3 ta porjonto service bondho thakbe. Details: {_legit_url(org)}",
             "bs": f"{org}: আজ রাত ১টা থেকে ৩টা পর্যন্ত সার্ভিস বন্ধ থাকবে।"}[lang]
    return t, 0, set(), 0


CORES = {0: legit, 1: mfs_scam, 2: prize_scam, 3: job_scam, 4: parcel_scam, 5: promo}
CHATTER = {"en": ["Hi, how are you?", "hello?", "who is this?", "ok", "I am fine, thanks", "what is it about?", "really?", "hmm"],
           "bn": ["Assalamu alaikum, kemon achen?", "ke bolchen?", "hmm bolen", "accha", "ki bepar?", "ok bhai", "sotti?"],
           "bs": ["আসসালামু আলাইকুম, কেমন আছেন?", "কে বলছেন?", "জি বলুন", "আচ্ছা", "কী ব্যাপার?", "সত্যি?"]}
MARKERS = [("S:", "R:"), ("A:", "B:"), ("[Sender]", "[You]"), ("Caller:", "You:"), (None, None)]


def _sentences(text):
    parts = [p.strip() for p in text.replace("! ", "!|").replace(". ", ".|").replace("। ", "।|").split("|") if p.strip()]
    return parts or [text]


def wrap(r, text, label, lang):
    """Present a core message in a different register (domain shift) - same labels."""
    k = r.random()
    if k < 0.45:
        return text
    if k < 0.75:  # multi-turn chat, decisive request revealed late
        me, them = r.choice(MARKERS)
        turns, sents = [], _sentences(text)
        for _ in range(r.randint(1, 3)):
            turns.append((me, r.choice(CHATTER[lang])))
            turns.append((them, r.choice(CHATTER[lang])))
        for s in sents:
            turns.append((me, s))
            if r.random() < 0.4:
                turns.append((them, r.choice(CHATTER[lang])))
        return " ||| ".join(f"{m} {s}" if m else s for m, s in turns[:12])
    if k < 0.85:  # group chat
        n = r.sample(NAMES, 3)
        return " ||| ".join([f"[Group] {n[0]}: {r.choice(CHATTER[lang])}", f"[Group] {n[1]}: {text}",
                             f"[Group] {n[2]}: {r.choice(CHATTER[lang])}"])
    if k < 0.95:  # formal email
        return f"Subject: Important notice. Dear Customer, {text} Regards, Customer Service Team"
    return f"Notice: {text} This message is sent to all registered users. For any query please contact the help desk during office hours."


def generate(n_per_class=200, seed=42, langs=("en", "bn", "bs"), lang_weights=(0.45, 0.4, 0.15), urgency_rate=0.3):
    """DataFrame with text, label, action, techniques ('T1|T2' or 'NONE')."""
    r = random.Random(seed)
    rows = []
    for label, core in CORES.items():
        for _ in range(n_per_class):
            lang = r.choices(langs, lang_weights)[0]
            text, y, tech, act = core(r, lang)
            tech = set(tech)
            if y in (1, 2, 3, 4) and r.random() < urgency_rate:   # extra pressure line -> T5
                text += " " + {"en": r.choice(URGENT_EN), "bn": r.choice(URGENT_BN), "bs": r.choice(URGENT_BS)}[lang]
                tech.add("T5")
            rows.append({"text": wrap(r, text, y, lang), "label": y, "action": act,
                         "techniques": "|".join(sorted(tech)) if tech else "NONE"})
    return pd.DataFrame(rows)
